# 目的：整块加入或整块跳过，不能只截取结论的一半。字符预算只是入门观察工具。
# 预期：最多 2400 字符的候选证据进入请求。
def budget(hits, maximum=2400):
    result, used = [], 0
    for hit in hits:
        if used + len(hit["text"]) > maximum:
            continue
        result.append(hit)
        used += len(hit["text"])
    return result

