# 目的：三个人工字段必须分别为 true，证据不足行为也要匹配预期；少一项就不能放行。
# 预期：未评分的报告会失败，不能用缺省值蒙混过去。
def quality_gate(report_file):
    report = json.loads(Path(report_file).read_text(encoding="utf-8"))
    failures = []
    if not report.get("generated") or not report.get("records"):
        failures.append("没有真实生成记录。")
    for item in report.get("records", []):
        if item.get("error_type") or not item.get("response"):
            failures.append(f"{item['id']} 没有成功响应。")
        if not all(item.get("manual", {}).get(k) is True for k in ("answer_supported", "citation_supported", "age_appropriate")):
            failures.append(f"{item['id']} 缺少逐项人工通过结论。")
        if item.get("response", {}).get("insufficient") is not item.get("expected_insufficient"):
            failures.append(f"{item['id']} 的证据不足行为未达到预期。")
    return {"passed": not failures, "failures": failures,
            "scope": "仅这份题集的记录；不是生产容量、教学效果或公司上线批准"}

# 目的：一次进程只加载一次真实 CPU 编码器，不用字符计数伪造向量。
# 预期：文本列表变成等长浮点向量列表，保留输入顺序。
@lru_cache(maxsize=1)
def encoder():
    from sentence_transformers import SentenceTransformer
    # CPU 是两种生成模型路线共同的起点；首次会下载权重，不能当作离线已准备好。
    # 显式指定公开仓库提交，不依赖库的私有配置字段，也不跟随会移动的 main。
    return SentenceTransformer(MODEL, revision=MODEL_REVISION, device="cpu", cache_folder=str(data_dir() / "models"))

# 目的：先查 token 长度，超窗就停止；归一化后的向量可以用点积比较。
# 预期：文本列表变成等长浮点向量列表，保留输入顺序。
def embed(texts):
    model = encoder()
    lengths = [len(model.tokenizer.encode(t, add_special_tokens=True)) for t in texts]
    if any(length > model.max_seq_length for length in lengths):
        raise ValueError(f"片段超过 Embedding 的 {model.max_seq_length} token 窗口，请减小切块；不静默截断。")
    return model.encode(texts, batch_size=8, normalize_embeddings=True).tolist()

