# 目的：检索小块容易缺少前因；只补同一父段落附近内容，避免把不相关文档拼在一起。
# 预期：每个块只出现一次，范围过滤在扩展前已经完成。
def neighbors(hits, chunks):
    selected = {c["id"]: c for c in hits}
    for hit in hits:
        siblings = sorted((c for c in chunks if c["doc_id"] == hit["doc_id"] and c["parent"] == hit["parent"]), key=lambda c: c["start"])
        position = next((i for i, c in enumerate(siblings) if c["id"] == hit["id"]), -1)
        if position >= 0:
            for item in siblings[max(0, position - 1):position + 2]:
                selected[item["id"]] = item
    return list(selected.values())

# 目的：词面分数和向量分数的尺度不同；先按名次融合，避免直接把两种分数相加。
# 预期：去重后的前五条保留来源信息。
def fuse(first, second, k=5):
    scores, items = {}, {}
    for result in (first, second):
        for position, item in enumerate(result, 1):
            items[item["id"]] = item
            scores[item["id"]] = scores.get(item["id"], 0) + 1 / (60 + position)
    return [{**items[key], "score": scores[key]} for key in sorted(scores, key=lambda x: (-scores[x], x))[:k]]

# 目的：重排可能更贵，也可能错；要求返回完整候选排列，不能新增或漏掉来源。
